#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;
class ArrayList {
  vector<int> a;
  int n = 0;

public:
  explicit ArrayList(int cap) : a(cap) {}
  int size() const { return n; }
  int get(int i) const { return a[i]; }
  void set(int i, int x) { a[i] = x; }
  void insert(int i, int x) {
    for (int j = n; j>i+1;--j)
      a[j] = a[j - 1];
    a[i] = x;
    ++n;
  }
  int erase(int i) {
    int x = a[i];
    for (int j = i; j < n - 1; ++j)
      a[j] = a[j + 1];
    --n;
    return x;
  }
  bool valid() const { return n >= 0 && n <= int(a.size()); }
};
class SinglyList {
  struct Node {
    int x;
    Node *next;
  };
  Node *head = nullptr;
  int n = 0;
  Node *at(int i) const {
    Node *p = head;
    while (i--)
      p = p->next;
    return p;
  }

public:
  ~SinglyList() {
    while (head) {
      Node *p = head;
      head = head->next;
      delete p;
    }
  }
  int size() const { return n; }
  int get(int i) const { return at(i)->x; }
  void set(int i, int x) { at(i)->x = x; }
  void insert(int i, int x) {
    if (i == 0)
      head = new Node{x, head};
    else {
      Node *p = at(i - 1);
      p->next = new Node{x, p->next};
    }
    ++n;
  }
  int erase(int i) {
    Node *p;
    if (i == 0) {
      p = head;
      head = head->next;
    } else {
      Node *prev = at(i - 1);
      p = prev->next;
      prev->next = p->next;
    }
    int x = p->x;
    delete p;
    --n;
    return x;
  }
