      cout << "invalid";
    else {
      long long visits = 0;
      Node *p = head;
      for (long long j = 0; j<i;++j) {
        ++visits;
        p = p->next;
      }
      volatile long long value = a[i];
      (void)value;
      cout << 1 << ',' << visits;
    }
    long long insertion = 0;
    vector<long long> inserted = a;
    for (long long j = n; j > i; --j) {
      inserted[j] = inserted[j - 1];
      ++insertion;
    }
