  vector<int> degree(n), order;
  for (int i = 0; i < m; ++i) {
    auto &e = edges[i];
    cin >> e.u >> e.v >> e.w;
    if (e.w < 0) {
      cout << "invalid\n";
      return 0;
    }
    adj[e.u].push_back(i);
    ++degree[e.v];
  }
