      q.push(i);
  while (!q.empty()) {
    int u = q.front();
    q.pop();
    order.push_back(u);
    for (int id : adj[u])
      if (--degree[edges[id].v] == 0)
        q.push(edges[id].v);
  }
  if (int(order.size()) != n) {
    cout << "cycle\n";
    return 0;
  }
  vector<long long> early(n), late(n);
  for (int u : order)
    for (int id : adj[u]) {
      auto &e = edges[id];
      early[e.v] = max(early[e.v], early[u] + e.w);
    }
  fill(late.begin(), late.end(), *max_element(early.begin(), early.end()));
  for (auto it = order.rbegin(); it != order.rend(); ++it)
    for (int id : adj[*it]) {
      auto &e = edges[id];
      late[e.u]=late[e.v]-e.w;
    }
  auto print = [&](const char *name, const vector<long long> &row) {
