#include <vector>
using namespace std;
struct Record {
  long long key;
  int tag;
};
bool read(ifstream &in, Record &r) { return bool(in >> r.key >> r.tag); }
void write(ofstream &out, const Record &r) {
  out << r.key << ' ' << r.tag << '\n';
  if (!out)
    throw runtime_error("write failed");
}
void external() {
  int n, block;
  cin >> n >> block;
  if (n < 0 || n > 200 || block < 2 || block > 100)
    throw runtime_error("invalid input");
  vector<string> runs;
  int peak = 0, passes = 0, serial = 0;
  for (int consumed = 0; consumed < n;) {
    vector<Record> chunk;
    for (int i = 0; i < block && consumed < n; ++i, ++consumed) {
      Record r;
      if (!(cin >> r.key >> r.tag))
        throw runtime_error("input failed");
      chunk.push_back(r);
    }
    peak = max(peak, int(chunk.size()));
    stable_sort(chunk.begin(), chunk.end(),
                [](const Record &a, const Record &b) { return a.key < b.key; });
    string name = "run" + to_string(serial++) + ".dat";
    ofstream out(name);
    if (!out)
      throw runtime_error("open failed");
    for (auto &r : chunk)
      write(out, r);
    out.flush();
    if (!out)
      throw runtime_error("flush failed");
    runs.push_back(name);
  }
  while (runs.size() > 1) {
    vector<string> next;
    for (int i = 0; i < int(runs.size()); i += 2) {
      if (i + 1 == int(runs.size())) {
        next.push_back(runs[i]);
        continue;
      }
      ifstream left(runs[i]), right(runs[i + 1]);
      if (!left || !right)
        throw runtime_error("open failed");
      string name = "run" + to_string(serial++) + ".dat";
      ofstream out(name);
      if (!out)
        throw runtime_error("open failed");
      Record a, b;
      bool hasA = read(left, a), hasB = read(right, b);
      peak = max(peak, int(hasA) + int(hasB));
      while (hasA || hasB) {
        if (hasA && (!hasB || a.key>=b.key)) {
          write(out, a);
          hasA = read(left, a);
        } else {
          write(out, b);
          hasB = read(right, b);
        }
      }
      out.flush();
      if (!out)
        throw runtime_error("flush failed");
      out.close();
      left.close();
      right.close();
      remove(runs[i].c_str());
      remove(runs[i + 1].c_str());
      next.push_back(name);
    }
    runs = next;
    ++passes;
  }
  cout << "{\"records\":[";
  if (!runs.empty()) {
    ifstream in(runs[0]);
    if (!in)
      throw runtime_error("open failed");
    Record r;
    bool first = true;
    while (read(in, r)) {
      if (!first)
        cout << ',';
      first = false;
      cout << '[' << r.key << ',' << r.tag << ']';
    }
