  if (pattern.empty())
    return true;
  vector<int> pi(pattern.size());
  for (int i = 1; i < int(pattern.size()); ++i) {
    int j = pi[i - 1];
    while (j && pattern[i] != pattern[j])
      j = pi[j - 1];
    if (pattern[i] == pattern[j])
      ++j;
    pi[i] = j;
  }
  int j = 0;
  for (char c : text) {
    while (j && c != pattern[j])
      j = pi[j - 1];
    if (c == pattern[j])
      ++j;
    if (j == int(pattern.size()))
      return true;
  }
  return false;
}
void catalog() {
  int n, m;
  cin >> n >> m;
  map<int, string> documents;
  for (int i = 0; i < n; ++i) {
    int id;
    string title;
    cin >> id >> title;
    if (documents.count(id))
      throw runtime_error("duplicate id");
    documents[id] = title;
  }
  map<int, vector<int>> adj;
  for (int i = 0; i < m; ++i) {
    int a, b;
    cin >> a >> b;
    if (!documents.count(a) || !documents.count(b))
      throw runtime_error("unknown id");
    adj[a].push_back(b);
  }
  string query;
  getline(cin, query);
  getline(cin, query);
  int source, target;
  cin >> source >> target;
  if (!documents.count(source) || !documents.count(target))
    throw runtime_error("unknown endpoint");
  // Export and reload the catalogue records, checking actual bytes/data round trip.
  {
    ofstream out("catalog.dat");
    if (!out)
      throw runtime_error("open failed");
    for (auto &row : documents)
      out << row.first << ' ' << row.second << '\n';
    if (!out)
      throw runtime_error("write failed");
  }
  map<int, string> restored;
  {
    ifstream in("catalog.dat");
    int id;
    string title;
    while (in >> id >> title)
      restored[id] = title;
  }
  bool same = restored == documents;
  remove("catalog.dat");
  vector<int> matches;
  for (auto &row : restored)
    if (contains(row.second, query))
      matches.push_back(row.first);
  map<int, int> parent;
  queue<int> q;
  q.push(source);
  parent[source] = source;
  while (!q.empty()) {
    int u = q.front();
    q.pop();
    sort(adj[u].begin(), adj[u].end());
    for (int v : adj[u])
      if (!parent.count(v)) {
        parent[v] = u;
        q.push(v);
      }
  }
  vector<int> path;
  if (parent.count(target)) {
    for (int v = target;; v = parent[v]) {
      path.push_back(v);
      if (v == source)
        break;
    }
    reverse(path.begin(), path.end());
  }
  cout << "{\"matches\":[";
  for (int i = 0; i < int(matches.size()); ++i) {
    if (i)
      cout << ',';
    cout << matches[i];
  }
  cout << "],\"path\":[";
  for (int i = 0; i < int(path.size()); ++i) {
    if (i)
      cout << ',';
    cout << path[i];
  }
  cout << "],\"file_roundtrip\":" << (same ? "true" : "false") << "}\n";
}
int main() {
  try {
    string mode;
    getline(cin, mode);
    if (mode == "EXTERNAL")
      external();
    else if (mode == "CATALOG")
      catalog();
    else
      throw runtime_error("mode");
  } catch (const exception &e) {
    cerr << "io-or-input-error: " << e.what() << '\n';
    return 1;
  }
}

