  int size = 0;
  string operation;
  while (cin >> operation) {
    if (operation == "push_front" || operation == "push_back") {
      long long value;
      if (!(cin >> value))
        return 1;
      if (size == capacity) {
        cout << "full\n";
      } else if (operation == "push_front") {
        head = (head + 1) % capacity;
        values[head] = value;
        ++size;
