        cout << values[head] << '\n';
        head = (head + 1) % capacity;
        --size;
      }
    } else if (operation == "pop_back") {
      if (size == 0) {
        cout << "empty\n";
      } else {
        cout << values[(head + size - 1) % capacity] << '\n';
        --size;
      }
    } else if (operation == "front" || operation == "back") {
      if (size == 0) {
        cout << "empty\n";
      } else {
